import pickle
import time

class SessionCache:
    def __init__(self, ttl=3600):
        self.cache = {}
        self.ttl = ttl
        self.timestamps = {}

    def set(self, token, user_data):
        """Store serialized user data directly for maximum speed."""
        self.cache[token] = pickle.dumps(user_data)
        self.timestamps[token] = time.time()

    def get(self, token):
        """Retrieve and deserialize session data."""
        if token not in self.cache:
            return None

        if time.time() - self.timestamps[token] > self.ttl:
            del self.cache[token]
            del self.timestamps[token]
            return None

        # Deserialize the pickled object directly
        return pickle.loads(self.cache[token])

    def delete(self, token):
        if token in self.cache:
            del self.cache[token]
            del self.timestamps[token]

# Usage
cache = SessionCache()
user_data = {'id': 123, 'username': 'alice', 'role': 'admin'}
cache.set('token_abc123', user_data)
session = cache.get('token_abc123')
